import React, { useState } from 'react';
import { useLanguage } from '../../context/LanguageContext';

const LanguageSelector = ({ type }) => {
  const { language, nativeLanguage, changeLanguage, changeNativeLanguage, appData } = useLanguage();
  const [isOpen, setIsOpen] = useState(false);

  const currentLanguage = type === 'learning' ? language : nativeLanguage;
  const handleLanguageChange = type === 'learning' ? changeLanguage : changeNativeLanguage;

  // Default languages if appData is not loaded yet
  const defaultLanguages = [
    { code: 'pt', flag: 'br', name: 'Português', shortName: 'PT' },
    { code: 'en', flag: 'us', name: 'English', shortName: 'EN' },
    { code: 'es', flag: 'es', name: 'Español', shortName: 'ES' },
    { code: 'fr', flag: 'fr', name: 'Français', shortName: 'FR' },
    { code: 'de', flag: 'de', name: 'Deutsch', shortName: 'DE' },
    { code: 'it', flag: 'it', name: 'Italiano', shortName: 'IT' },
    { code: 'ru', flag: 'ru', name: 'Русский', shortName: 'RU' },
    { code: 'ja', flag: 'jp', name: '日本語', shortName: 'JP' },
    { code: 'ko', flag: 'kr', name: '한국어', shortName: 'KO' },
    { code: 'zh', flag: 'cn', name: '中文', shortName: 'ZH' },
    { code: 'hi', flag: 'in', name: 'हिन्दी', shortName: 'HI' }
  ];

  const languages = appData?.languages || defaultLanguages;
  const selectedLanguage = languages.find(lang => lang.code === currentLanguage) || languages[0];

  const handleSelect = (langCode) => {
    handleLanguageChange(langCode);
    setIsOpen(false);
  };

  return (
    <div className="language-selector-wrapper">
      <div className={`language-selector ${isOpen ? 'active' : ''}`}>
        <div 
          className="selected-language"
          onClick={() => setIsOpen(!isOpen)}
        >
          <img 
            src={`/flags/${selectedLanguage.flag}.svg`} 
            alt={selectedLanguage.name}
            className="flag-icon"
          />
          {type === 'interface' && <span>{selectedLanguage.shortName}</span>}
          <i className="fas fa-chevron-down dropdown-icon"></i>
        </div>

        <ul className={`language-options ${isOpen ? 'show' : ''}`}>
          {languages.map((lang) => (
            <li 
              key={lang.code}
              data-value={lang.code}
              data-flag={lang.flag}
              className={currentLanguage === lang.code ? 'selected' : ''}
              onClick={() => handleSelect(lang.code)}
            >
              <img 
                src={`/flags/${lang.flag}.svg`} 
                alt={lang.name}
                className="flag-icon"
              />
              <span>{type === 'interface' ? lang.name : lang.name}</span>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
};

export default LanguageSelector;
